"""Generates docs/product/curriculum/CUR-001-curriculum-map.md from its data (CUR-001).

Usage: python3 -I docs/product/verification/build-curriculum-map-doc.py

Inputs (all in docs/product/curriculum/):
  curriculum-map.csv                      the authored map (one row per statutory statement, plus extension candidates)
  evidence/dfe-maths-pos-y2-y6.json       the statutory wording, extracted verbatim from the official DfE page
  evidence/islands-snapshot.json          the existing islands, skills and lessons on the retrieval date
Edit the CSV, then rerun this script; src/curriculum/map.test.ts checks the CSV against the sources and the document.
"""
import csv, json, re
from collections import Counter, defaultdict
from pathlib import Path

C = Path("docs/product/curriculum")
rows = list(csv.DictReader(open(C / "curriculum-map.csv", encoding="utf-8")))
dfe = json.load(open(C / "evidence/dfe-maths-pos-y2-y6.json", encoding="utf-8"))
isl = json.load(open(C / "evidence/islands-snapshot.json", encoding="utf-8"))
stmt = {st["id"]: st["text"] for s in dfe["sections"] for st in s["statements"]}
src = dfe["source"]
stat = [r for r in rows if r["status"] == "statutory"]
ext = [r for r in rows if r["status"] != "statutory"]
skill_island = {s["id"]: t["id"] for t in isl for s in t["skills"]}
skill_title = {s["id"]: s["title"] for t in isl for s in t["skills"]}

KINDS = {
    "F": ("Fluency and recall", "Independent, first-attempt answers to **mixed** (not sequential) items, with no hint and no revealed answer, re-checked after a gap (spaced), including the related facts or the inverse."),
    "R": ("Representation and concept", "Independent identification or use of the idea across **at least two representations**, including one not used in teaching."),
    "P": ("Procedure", "Independent completion of **fresh** calculations by the method, each checked by an inverse operation or an estimate."),
    "X": ("Reasoning and explanation", "Independent justification, explanation or counterexample, using the lesson's sentence frames or the learner's own words (CUR-003 reflection rules)."),
    "W": ("Problems in context", "Independent solution of **unfamiliar** contextual problems where the learner chooses the operation, with transfer to a new context."),
    "V": ("Vocabulary, reading and writing", "Independent reading, writing or naming across varied cases, including edge cases (for example zero as a place holder)."),
}
def kind_label(k): return " + ".join(KINDS[x][0].split(" and ")[0].lower() if False else f"{x}" for x in k.split("+"))
def mastery_cell(k): return " + ".join(f"**{x}** {KINDS[x][0]}" for x in k.split("+"))
def esc(s): return s.replace("|", "\\|")
def skills_cell(s): return "<br>".join(f"`{x}`" for x in s.split(";") if x) or "—"
COVER = {"addressed": "Addressed", "partial": "Partial", "not-addressed": "Not addressed"}
def tag(r): return f"{r['id']}" + (f"<br>**R1: {r['r1_role']}**" if r["r1_role"] else "")

out = []
w = out.append
w("<!-- Generated by docs/product/verification/build-curriculum-map-doc.py from curriculum-map.csv. Edit the CSV, not this file. -->")
w("# CUR-001 — Year 3–6 curriculum map\n")
w("| | |\n|---|---|")
w("| **Backlog item** | CUR-001: build the Year 3–6 curriculum map (P0, R0) |")
w("| **Status** | READY FOR QA, waiting for Product Owner and educational QA review |")
w("| **Date** | 6 November 2026 |")
w("| **Acceptance criteria** | <ol><li>Each objective has year group, strand, prerequisite, expected knowledge, key vocabulary, examples, mastery evidence and source.</li><li>Statutory curriculum and optional 11+ extension are labelled separately.</li><li>Year allocation is verified against official sources.</li></ol> |")
w("| **Deliverables** | <ul><li>This map.</li><li>The data: [`curriculum-map.csv`](curriculum-map.csv).</li><li>The sources: [`evidence/`](evidence/).</li><li>The checks: `src/curriculum/map.test.ts`.</li></ul> |")
w("| **Scope** | Mapping and review only. No island was added or changed, and no screen changed. |")
w("\n---\n")

w("## 1. What this map is, and what it is not\n")
w(f"- **{len(stat)} objectives.** One objective is one statutory statement of the national curriculum maths programme of study for Years 3 to 6 (Year 3: {sum(r['year']=='3' for r in stat)}, Year 4: {sum(r['year']=='4' for r in stat)}, Year 5: {sum(r['year']=='5' for r in stat)}, Year 6: {sum(r['year']=='6' for r in stat)}). Its wording is the Department for Education's, quoted verbatim.")
w("- **Sourced, and ours, are kept apart.**")
w("  - **Sourced (DfE):** the objective id, year group, strand and the statement text, and where it is located (§2).")
w("  - **Our instructional choices:** the learner outcome, prerequisite knowledge, vocabulary, examples, proposed mastery evidence, the mapping to islands and skills, and the coverage judgement. None of these is claimed to be in the programme of study.")
w("- **Year allocation is verified against the official source, not inferred from island labels** (§2.2). It also carries a caveat the source states itself (§2.2): schools need only teach the programme by the end of the key stage.")
w("- **Statutory and 11+ are separate.** §6 lists extension candidates. The 11+ has **no single official specification** (§6), so no extension item has an official source, and none is labelled as required by any 11+ test.")
w("- **Mastery thresholds are not set here.** The mastery evidence says *what kind* of evidence would show the objective is secure. How many items, and what threshold, is owned by MAST-001 (CUR-002 §4.3).")
w("- **Coverage is a desk judgement.** \"Addressed\", \"partial\" and \"not addressed\" compare each statement with the **titles and descriptions** of the existing skills and lessons. Nobody reviewed the question content for this map. For Fractions that review is CUR-004. For other islands it comes with R4. Only the Fractions island (`fractions.*`) is the R1 product; the 18 other islands are unaccepted previews (D-001).")
w("- This is **mapping and review**, not implementation. Gaps in §7 are inputs to later releases, not defects.\n")

w("## 2. Source and year allocation (AC3)\n")
w("### 2.1 The source\n")
w("| | |\n|---|---|")
w(f"| **Document** | {src['title']} |\n| **Publisher** | {src['publisher']} |\n| **URL** | <{src['url']}> |")
w(f"| **Page last modified** | {src['page_last_modified'][:10]} |\n| **Retrieved** | {src['retrieved']} |\n| **Licence** | {src['licence']} |")
w("| **Extraction** | [`verification/extract-dfe-curriculum.py`](../verification/extract-dfe-curriculum.py) saves the statements to [`evidence/dfe-maths-pos-y2-y6.json`](evidence/dfe-maths-pos-y2-y6.json). It keeps the wording verbatim: the page's fraction markers become `a/b`, entities are decoded and spaces collapsed. |")
w("\n**How to find a statement.** Open the URL with the section's anchor, then count the bullets. Objective `Y3.FRAC.2` is the second bullet under the section `Number - fractions` in the *Year 3 programme of study*, at `<URL>#number---fractions-2`. Each strand table below states its anchor. Bullets with sub-points are one objective.\n")
w("### 2.2 Year allocation\n")
w("The programme of study is set out **year by year**, and each statement's year is the year of the section it sits in. The same source also says (verbatim, under *School curriculum*):\n")
w("> " + dfe["school_curriculum"][0] + "\n")
w("So a year group here is the programme's own sequence, **not a requirement to teach in that year**: the statutory duty is by the end of the key stage (Year 4 for lower KS2, Year 6 for upper KS2). Product recommendations by year are our choice (PARENT-001). One statement in the key stage 2 introduction does fix a year: pupils should have memorised their multiplication tables up to and including 12 × 12 **by the end of Year 4**. (The Year 4 Multiplication Tables Check is described in the backlog's TT epic; its official guidance was not verified for this map.)\n")
w("**The island labels were checked, not trusted** (§4.3). Where an island's `years` disagree with the statutory years of the objectives it covers, the table says so.\n")

w("## 3. Proposed mastery evidence, by kind\n")
w("Each objective names one or more kinds. Every kind assumes the CUR-002 §4 contract: **independent** means first attempt, no hint, answer not revealed, a fresh item. How many items count, and the threshold, belong to MAST-001.\n")
w("| Kind | Proposed evidence |\n|---|---|")
for k, (n, t) in KINDS.items(): w(f"| **{k}** {n} | {t} |")
w("")

w("## 4. Summary\n")
w("### 4.1 Coverage by year\n")
w("| Year | Objectives | Addressed | Partial | Not addressed |\n|---|---:|---:|---:|---:|")
for y in "3456":
    c = Counter(r["coverage"] for r in stat if r["year"] == y)
    w(f"| {y} | {sum(c.values())} | {c['addressed']} | {c['partial']} | {c['not-addressed']} |")
c = Counter(r["coverage"] for r in stat)
w(f"| **All** | **{len(stat)}** | **{c['addressed']}** | **{c['partial']}** | **{c['not-addressed']}** |\n")
w("### 4.2 Fractions R1 dependencies\n")
w("The R1 Fractions island has 8 skills: `fractions.equal-parts`, `.name`, `.represent`, `.compare`, `.equivalent`, `.number-line`, `.fraction-of` and `.reasoning`. The table lists every objective that the island teaches (**taught**), that must be in place before it (**prerequisite**), or that builds on it and is taught elsewhere (**builds-on**: Fractions 2, Decimals and Percentages previews, R4). Year 2 prerequisites are `Y2.FRAC.1`, `Y2.FRAC.2`, `Y2.MD.1` and `Y2.NPV.3`; they are in the extracted source but not mapped here.\n")
w("| Objective | Year | Statement | R1 role | Skills (the R1 island for taught, otherwise related) | Coverage and gap |\n|---|---:|---|---|---|---|")
role_order = {"taught": 0, "prerequisite": 1, "builds-on": 2}
for r in sorted([r for r in stat if r["r1_role"]], key=lambda r: (role_order[r["r1_role"]], r["id"])):
    r1 = ";".join(x for x in r["skills"].split(";") if x.startswith("fractions.")) if r["r1_role"] == "taught" else r["skills"]
    w(f"| {r['id']} | {r['year']} | {esc(stmt[r['id']])} | **{r['r1_role']}** | {skills_cell(r1)} | {COVER[r['coverage']]}{('. ' + esc(r['gap'])) if r['gap'] else ''} |")
w("\n**Reading this table.**")
taught = [r for r in stat if r["r1_role"] == "taught"]
w(f"- The island teaches {len(taught)} objectives, all from the Number: fractions strand ({', '.join(r['id'] for r in taught)}).")
w("- Not taught by the R1 island, although they are Year 3–5 fractions objectives: **adding and subtracting fractions** (Y3.FRAC.5, Y4.FRAC.4, Y5.FRAC.4), **fractions greater than 1 and mixed numbers** (Y5.FRAC.3), **comparison with different denominators** (Y5.FRAC.1) and **tenths and hundredths as decimals** (Y3.FRAC.1, Y4.FRAC.2). Whether R1 should include any of them is a Product Owner decision (§8).")
w("- `fractions.fraction-of` needs division facts (Y3.MD.1, Y4.MD.1). CUR-002 makes this a \"best after\" recommendation, never a lock (D-019).\n")
w("### 4.3 Island year labels against the programme of study\n")
w("For each island, the years of the objectives mapped to it (addressed or partial) against the island's own `years` label. A year in the label with no mapped objective may be wrong or may reflect content beyond the mapping.\n")
w("| Island | Label | Statutory years of mapped objectives | Check |\n|---|---|---|---|")
for t in isl:
    mapped = sorted({int(r["year"]) for r in stat if r["coverage"] != "not-addressed" and any(skill_island.get(s) == t["id"] for s in r["skills"].split(";") if s)})
    label = sorted(t["years"])
    extra = [y for y in label if y >= 3 and y not in mapped]; missing = [y for y in mapped if y not in label]  # the map starts at Year 3
    y2 = " (Year 2 is outside this map)" if 2 in label else ""
    note = "matches" if not extra and not missing else ("; ".join(filter(None, [f"label has years with no mapped objective: {', '.join(map(str, extra))}" if extra else "", f"mapped objectives in years not labelled: {', '.join(map(str, missing))}" if missing else ""])))
    w(f"| `{t['id']}` | {', '.join(map(str, label))} | {', '.join(map(str, mapped)) or '—'} | {note}{y2} |")
w("\nA difference is a prompt to review the label or the mapping, **not a defect**: the island labels describe where content is pitched, and a mapped objective can sit in a later year than the island's label (for example Fractions reaches Year 6 only through comparison). `mock-exams` maps to nothing on purpose (§6). Corrections to labels belong with PARENT-001 (§8).\n")

w("## 5. The objective map (AC1)\n")
w("Columns: **Objective** (DfE statement, verbatim) · **Outcome**, **Prerequisites**, **Vocabulary**, **Examples**, **Mastery evidence** (kinds in §3) · **Maps to** (existing skill ids) · **Coverage and gap**. The year, strand and source are in each heading; the objective id ends with its position in the source section.\n")
by = defaultdict(list)
for r in stat: by[(r["year"], r["strand"], r["source_anchor"])].append(r)
cur_year = None
for (year, strand, anchor), rs in by.items():
    if year != cur_year:
        w(f"### Year {year} ({rs[0]['key_stage']})\n"); cur_year = year
    w(f"#### Year {year} · {strand}\n")
    w(f"Source: <{src['url']}#{anchor}> · statutory · statements 1 to {len(rs)}\n")
    w("| Objective | Outcome | Prerequisites | Vocabulary | Examples | Mastery evidence | Maps to | Coverage and gap |\n|---|---|---|---|---|---|---|---|")
    for r in rs:
        gap = f"**{COVER[r['coverage']]}**" + (f". {esc(r['gap'])}" if r["gap"] else "")
        w(f"| {tag(r)}<br>{esc(stmt[r['id']])} | {esc(r['outcome'])} | {esc(r['prerequisites'])} | {esc(r['vocabulary'])} | {esc(r['examples'])} | {mastery_cell(r['mastery_kind'])} | {skills_cell(r['skills'])} | {gap} |")
    w("")

w("## 6. Optional 11+ extension (AC2)\n")
w("**There is no single official 11+ specification.** The 11+ is set by individual grammar schools, local authorities and consortia, using providers such as GL Assessment or CEM, and its content and format vary by area and provider. The sources I found while building this map were commercial or anecdotal and disagreed on how far 11+ maths reaches into Year 6; I could not find an exam provider's own specification. The backlog's own rule applies: do not describe all 11+ exams as one uniform syllabus (backlog §3). Verified exam profiles belong to EXAM-001 and EXAM-002 (R5).\n")
w("So this section lists only **extension candidates**: things the existing islands teach that go **beyond the statutory wording**. They are our instructional choices. They have **no official source**, and none is claimed to be required by any 11+ test.\n")
w("| Id | Candidate | Related statutory objectives | Maps to | Mastery evidence | Why it is an extension candidate |\n|---|---|---|---|---|---|")
for r in ext:
    w(f"| {r['id']} | {esc(r['outcome'])} Example: {esc(r['examples'])} | {esc(r['prerequisites'])} | {skills_cell(r['skills'])} | {mastery_cell(r['mastery_kind'])} | {esc(r['gap'])} |")
w("\nThe `mock-exams` island (\"11+ style\") is exam technique and format practice, not curriculum content. It is deliberately **not** used as evidence that any statutory objective is covered.\n")

w("## 7. Gaps\n")
w("Objectives **not addressed** by any existing skill, grouped by strand. These are inputs to R4 (curriculum expansion), not R1 defects.\n")
w("| Strand | Not addressed |\n|---|---|")
na = defaultdict(list)
for r in stat:
    if r["coverage"] == "not-addressed": na[r["strand"]].append(r["id"])
for s, ids in na.items(): w(f"| {s} | {', '.join(ids)} |")
w(f"\n**Totals:** {c['not-addressed']} not addressed, {c['partial']} partial, {c['addressed']} addressed, of {len(stat)}. Topics with nothing taught: measuring and converting length, mass and capacity, volume, symmetry, circles, primes, squares and cubes, order of operations, Roman numerals, long division, fraction multiplication and division, and measuring angles with a protractor.\n")

w("## 8. Decisions needed\n")
w("| # | Decision | Recommendation |\n|---|---|---|")
w("| 1 | Should the R1 Fractions island add adding and subtracting fractions (Y3.FRAC.5, Y4.FRAC.4)? The Fractions 2 preview already does. | Keep R1 to the 8 existing skills; promote Fractions 2 after its own review. Product Owner call. |")
w("| 2 | The Year 3 objectives Y3.FRAC.1 (tenths) and the Year 4 and 5 decimal objectives are taught on the Decimals preview. Is that acceptable for the Fractions R1 claim of \"Year 3–6 fractions\"? | Describe R1 honestly as the Year 3–4 foundations of fractions, not the whole strand. |")
w("| 3 | Which named 11+ profile(s) should the later extension target? | Decide in EXAM-001/002; until then the extension stays unlabelled as 11+. |")
w("| 4 | Island `years` labels: correct the mismatches in §4.3 now or in R1 (PARENT-001)? | Correct with the PARENT-001 year-group work; no screen change now. |\n")

w("## 9. Checks and maintenance\n")
w("`src/curriculum/map.test.ts` runs with `npm test` and checks that:")
w("- every Year 3–6 statutory statement in the extracted source is in the map exactly once, with the right year, strand, anchor and position;")
w("- every objective has every required field, a valid mastery kind and existing prerequisite ids, never from a later year, with no cycles;")
w("- every mapped skill exists, \"not addressed\" objectives map to nothing, and the R1 \"taught\" objectives map to Fractions skills;")
w("- extension candidates are separate, carry no source and are never labelled statutory;")
w("- the island snapshot matches the live islands, so the map is flagged when islands change;")
w("- this document lists every objective, and contains no invented mastery threshold.")
w("\nTo update: edit [`curriculum-map.csv`](curriculum-map.csv), then run `python3 -I docs/product/verification/build-curriculum-map-doc.py`. If the DfE page changes, rerun the extractor, review the diff, and update the map.")
open(C / "CUR-001-curriculum-map.md", "w", encoding="utf-8").write("\n".join(out) + "\n")
print("wrote", len(out), "lines;", len(stat), "objectives;", len(ext), "extension candidates")
